import re
from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class LncelFddParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]
        self.ch_bw = None

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.ch_bw = float(re.match(r'(.*) MHz', self.cell_ent.get('ch_bw', '10 MHz')).group(1))
        self.set_parameter('dlChBw', f'{self.ch_bw:g} MHz')
        self.set_parameter('ulChBw', f'{self.ch_bw:g} MHz')
        self.set_earfcnUL_and_earfcnDL()

        dl_mimo_mode = self.cell_ent.get('dl_mimo_mode', '')
        if dl_mimo_mode:
            self.set_parameter('dlMimoMode', dl_mimo_mode)
            self.set_dlMimoMode_dependencies(dl_mimo_mode)

        self.set_actAutoPucchAlloc(dl_mimo_mode, execution_config)
        self.set_chBw_dependencies()

    def set_earfcnUL_and_earfcnDL(self):
        earfcnUL = self.cell_ent.get('earfcn_ul')
        earfcnDL = self.cell_ent.get('earfcn_dl', 0)
        if not earfcnUL:
            earfcnUL = 18000 + int(earfcnDL)
        self.set_parameter('earfcnDL', earfcnDL)
        self.set_parameter('earfcnUL', earfcnUL)

    def set_actAutoPucchAlloc(self, dl_mimo_mode, execution_config):
        if execution_config['is_fsm5'] or dl_mimo_mode == 'Closed Loop MIMO (4x4)':
            self.set_parameter('actAutoPucchAlloc', 'true')

    def set_dlMimoMode_dependencies(self, dl_mimo_mode):
        if re.match(r'Closed Loop', dl_mimo_mode, re.I):
            self.set_struct_parameter('mimoClConfig', 'mimoClCqiThD', 70)
            self.set_struct_parameter('mimoClConfig', 'mimoClCqiThU', 80)
            self.set_struct_parameter('mimoClConfig', 'mimoClRiThD', 28)
            self.set_struct_parameter('mimoClConfig', 'mimoClRiThU', 36)

            self.set_parameter('twoLayerMimoAvSpectralEff', 1)
            actSdlc = self.cell_ent.get('act_sdlc', 'true')
            self.set_parameter('actSdlc', actSdlc)

        if dl_mimo_mode in ('Dynamic Open Loop MIMO', 'Closed Loop Mimo', 'Closed Loop MIMO (4x2)'):
            self.set_struct_parameter('mimoOlConfig', 'mimoOlCqiThD', 70)
            self.set_struct_parameter('mimoOlConfig', 'mimoOlCqiThU', 80)
            self.set_struct_parameter('mimoOlConfig', 'mimoOlRiThD', 28)
            self.set_struct_parameter('mimoOlConfig', 'mimoOlRiThU', 32)

            self.set_parameter('twoLayerMimoAvSpectralEff', 1)

        elif dl_mimo_mode == 'Closed Loop MIMO (4x4)':
            self.set_parameter('fourLayerMimoAvSpectralEff', 1)
            self.set_parameter('actFastMimoSwitch', 'true')

        if re.match(r'Closed Loop MIMO \(4x[42]\)', dl_mimo_mode):
            self.set_parameter('activatedMimoTM', 'TM4')

    def set_chBw_dependencies(self):
        if int(self.ch_bw) <= 5:
            self.set_parameter('addNumDrbRadioReasHo', 10)
            self.set_parameter('addNumDrbTimeCriticalHo', 10)
            self.set_parameter('addNumQci1DrbRadioReasHo', 10)
            self.set_parameter('addNumQci1DrbTimeCriticalHo', 10)

            self.set_parameter('maxNumActDrb', 20)
            self.set_parameter('maxNumActUE', 10)
            self.set_parameter('maxNumCaConfUe', 10)
            self.set_parameter('maxNumCaConfUe3c', 10)
            self.set_parameter('maxNumCaConfUeDc', 10)
            self.set_parameter('maxNumQci1Drb', 10)
            self.set_parameter('maxNumUeDl', 7)
            self.set_parameter('maxNumUeUl', 7)

        else:
            self.set_parameter('addNumDrbRadioReasHo', 35)
            self.set_parameter('addNumDrbTimeCriticalHo', 60)
            self.set_parameter('addNumQci1DrbRadioReasHo', 15)
            self.set_parameter('addNumQci1DrbTimeCriticalHo', 20)

            self.set_parameter('maxNumActDrb', 240)
            self.set_parameter('maxNumActUE', 240)
            self.set_parameter('maxNumCaConfUe', 50)
            self.set_parameter('maxNumCaConfUe3c', 20)
            self.set_parameter('maxNumCaConfUeDc', 50)
            self.set_parameter('maxNumQci1Drb', 100)
            self.set_parameter('maxNumUeDl', 14)
            self.set_parameter('maxNumUeUl', 14)

        if int(self.ch_bw) <= 1:
            self.set_parameter('maxNrSymPdcch', 4)
            self.set_parameter('prachFreqOff', 0)
        elif int(self.ch_bw) <= 3:
            self.set_parameter('maxNrSymPdcch', 3)
            self.set_parameter('prachFreqOff', 1)
        elif int(self.ch_bw) <= 5:
            self.set_parameter('maxNrSymPdcch', 3)
            self.set_parameter('prachFreqOff', 2)
        else:
            self.set_parameter('maxNrSymPdcch', 3)
            self.set_parameter('prachFreqOff', self.cell_ent.get('prachFreqOff', 5))
